import random, sys
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from fado_ref import fado_image
from ebpf.create_dfa import create, registry_columns
NAMES=['A','B','C','D','E']
def gen_path(rng,maxlen):
    return ','.join(rng.choice(NAMES) for _ in range(rng.randint(0,maxlen)))
def gen_pred(rng,depth):
    if depth>=4 or rng.random()<0.4:
        op=rng.choice(['match','match','startswith','endswith','contains'])
        return '%s(%s)'%(op,gen_path(rng,4 if op!='match' else 6))
    if rng.random()<0.25: return 'not(%s)'%gen_pred(rng,depth+1)
    return '(%s %s %s)'%(gen_pred(rng,depth+1),rng.choice(['and','or']),gen_pred(rng,depth+1))
def gen_policy(rng):
    return ' '.join('%s %s;'%(gen_pred(rng,0),rng.choice(['allow','allow','drop'])) for _ in range(rng.randint(0,5)))
seed=int(sys.argv[1]); count=int(sys.argv[2])
rng=random.Random(seed)
labels=rng.sample(range(1,4294967294),len(NAMES))
reg=[{'name':n,'label':labels[i]} for i,n in enumerate(NAMES)]
cols,colmap=registry_columns(reg)
bad=0; done=0; skip=0
for i in range(count):
    p=gen_policy(rng)
    try:
        got=create(p,cols,colmap); got={'accept':list(got.accept),'rows':[list(r) for r in got.rows]}
    except Exception as e:
        skip+=1; continue
    try:
        ref=fado_image(p,cols,colmap)
    except Exception as e:
        skip+=1; continue
    done+=1
    if got!=ref:
        bad+=1; print('DIFF',repr(p))
        print(' got',got['accept'],got['rows'][:8])
        print(' ref',ref['accept'],ref['rows'][:8])
        if bad>=3: break
print('fuzz_fado seed',seed,'checked',done,'bad',bad,'skip',skip)
PYEOF
